  KEY `idx_booking_confirmations_booking_id` (`booking_id`),
  KEY `idx_booking_confirmations_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=433 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
